public static class NativeInstaller {
 static NativeInstaller(){http.DefaultRequestHeaders.UserAgent.ParseAdd("084CN/0.2-preview");}
 public static string[] ComponentNames={"服务运行环境","IndexTTS2","但丁音色","旁白音色"};
 public static string[] ComponentPaths(int id){switch(id){case 0:return new[]{Path.Combine(Paths.Engines,"Runtime")};case 1:return new[]{Path.Combine(Paths.Engines,"IndexTTS2"),Path.Combine(Paths.Engines,"wetext-model"),Path.Combine(Paths.Engines,"nltk-data")};case 2:return new[]{Path.Combine(Paths.Engines,"voices/dante.wav")};case 3:return new[]{Path.Combine(Paths.Engines,"voices/narrator.wav")};default:throw new ArgumentOutOfRangeException("id");}}
 public static bool ComponentReady(int id){if(id==0)return CoreReady();if(id==1)return ModelReady();return File.Exists(ComponentPaths(id)[0]);}
 public static long ComponentSize(int id){long size=0;foreach(var p in ComponentPaths(id)){if(File.Exists(p))size+=new FileInfo(p).Length;else if(Directory.Exists(p))size+=Directory.EnumerateFiles(p,"*",SearchOption.AllDirectories).Sum(f=>new FileInfo(f).Length);}return size;}
 public static string FormatBytes(long n){if(n>=1073741824)return (n/1073741824.0).ToString("F2")+" GB";if(n>=1048576)return (n/1048576.0).ToString("F1")+" MB";return (n/1024.0).ToString("F1")+" KB";}
 public static long RequiredSize(int id){try{var d=Paths.Obj(Paths.Json.DeserializeObject(File.ReadAllText(Path.Combine(Paths.App,"EngineAdapter/component-sizes.json"))));return Convert.ToInt64(d[id.ToString()]);}catch{return id==0?300L*1048576:id==1?20L*1073741824:1048576;}}
 public static void DeleteComponent(int id){foreach(var target in ComponentPaths(id)){string full=Path.GetFullPath(target);if(!full.StartsWith(Path.GetFullPath(Paths.Engines)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("删除路径越界");if(File.Exists(full))File.Delete(full);else if(Directory.Exists(full))Directory.Delete(full,true);}}

 public static bool CoreReady(){return File.Exists(Paths.CorePython)&&File.Exists(Path.Combine(Path.GetDirectoryName(Paths.CorePython),".ready"))&&File.Exists(Path.Combine(Path.GetDirectoryName(Paths.CorePython),"Lib/site-packages/numpy/__init__.py"))&&File.Exists(Path.Combine(Path.GetDirectoryName(Paths.CorePython),"Lib/site-packages/scipy/__init__.py"))&&File.Exists(Path.Combine(Path.GetDirectoryName(Paths.CorePython),"Lib/site-packages/soundfile.py"));}
 public static bool ModelReady(){string folder=Path.Combine(Paths.Engines,"IndexTTS2");string[] required={".ready",".venv/python.exe",".venv/Lib/site-packages/torch/__init__.py",".venv/Lib/site-packages/transformers/__init__.py","checkpoints_2/gpt.pth","checkpoints_2/s2mel.pth","checkpoints_2/bpe.model","checkpoints_2/qwen0.6bemo4-merge/model.safetensors","checkpoints_2/hf_cache/w2v-bert-2.0/model.safetensors","checkpoints_2/hf_cache/semantic_codec_model.safetensors","checkpoints_2/hf_cache/campplus_cn_common.bin","checkpoints_2/hf_cache/bigvgan/bigvgan_generator.pt"};return required.All(p=>File.Exists(Path.Combine(folder,p)));}
 static async Task<string> Text(string url,CancellationToken token){using(var timeout=CancellationTokenSource.CreateLinkedTokenSource(token)){timeout.CancelAfter(45000);using(var response=await http.GetAsync(url,timeout.Token)){response.EnsureSuccessStatusCode();return await response.Content.ReadAsStringAsync();}}}
 static HttpClient http=new HttpClient(new HttpClientHandler{AllowAutoRedirect=true}){Timeout=Timeout.InfiniteTimeSpan};
 static string Combine(string root,string name){var p=Path.GetFullPath(Path.Combine(root,name.Replace('/',Path.DirectorySeparatorChar)));if(!p.StartsWith(Path.GetFullPath(root).TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))throw new IOException("拒绝越界路径："+name);return p;}
 static string Hex(byte[] b){return BitConverter.ToString(b).Replace("-","").ToLowerInvariant();}
 static string Digest(string path,bool git){using(var hash=git?(HashAlgorithm)SHA1.Create():SHA256.Create())using(var stream=File.OpenRead(path)){if(!git)return Hex(hash.ComputeHash(stream));byte[] header=Encoding.ASCII.GetBytes("blob "+stream.Length+"\0");hash.TransformBlock(header,0,header.Length,null,0);byte[] block=new byte[1024*1024];int n;while((n=stream.Read(block,0,block.Length))>0)hash.TransformBlock(block,0,n,null,0);hash.TransformFinalBlock(new byte[0],0,0);return Hex(hash.Hash);}}
 static async Task Download(string url,string path,long expected,string hash,bool git,Action<string,double> report,CancellationToken token){if(expected>64L*1024*1024&&!git&&!String.IsNullOrEmpty(hash)){await RangeDownload.Run(url,path,expected,hash,report,token);return;}Directory.CreateDirectory(Path.GetDirectoryName(path));report("正在检查："+Path.GetFileName(path),-1);if(File.Exists(path)&&(expected<=0||new FileInfo(path).Length==expected)&&(String.IsNullOrEmpty(hash)||await Task.Run(()=>Digest(path,git),token)==hash))return;string temp=path+".download";long start=File.Exists(temp)?new FileInfo(temp).Length:0;using(var request=new HttpRequestMessage(HttpMethod.Get,url)){if(start>0)request.Headers.Range=new System.Net.Http.Headers.RangeHeaderValue(start,null);using(var response=await http.SendAsync(request,HttpCompletionOption.ResponseHeadersRead,token)){if(response.StatusCode==HttpStatusCode.RequestedRangeNotSatisfiable){File.Delete(temp);throw new IOException("断点下载已失效，请重试。");}response.EnsureSuccessStatusCode();if(response.StatusCode!=HttpStatusCode.PartialContent)start=0;long total=expected>0?expected:(response.Content.Headers.ContentLength??0)+start;using(var input=await response.Content.ReadAsStreamAsync())using(var output=new FileStream(temp,start>0?FileMode.Append:FileMode.Create,FileAccess.Write,FileShare.None,1024*1024,true)){byte[] buffer=new byte[1024*1024];long done=start;int n;while((n=await input.ReadAsync(buffer,0,buffer.Length,token))>0){await output.WriteAsync(buffer,0,n,token);done+=n;report("正在下载 "+Path.GetFileName(path)+"\n"+(done/1048576.0).ToString("F1")+" / "+(total>0?(total/1048576.0).ToString("F1"):"未知")+" MB",total>0?done*100.0/total:-1);}}}}
 if(expected>0&&new FileInfo(temp).Length!=expected)throw new IOException("下载长度校验失败："+Path.GetFileName(path));report("正在校验："+Path.GetFileName(path),-1);if(!String.IsNullOrEmpty(hash)&&await Task.Run(()=>Digest(temp,git),token)!=hash){File.Delete(temp);throw new IOException("文件摘要校验失败："+Path.GetFileName(path));}token.ThrowIfCancellationRequested();if(File.Exists(path))File.Delete(path);File.Move(temp,path);}
 static void Unzip(string archive,string dest){Directory.CreateDirectory(dest);using(var zip=ZipFile.OpenRead(archive))foreach(var entry in zip.Entries){string path=Combine(dest,entry.FullName);if(entry.FullName.EndsWith("/")){Directory.CreateDirectory(path);continue;}Directory.CreateDirectory(Path.GetDirectoryName(path));entry.ExtractToFile(path,true);}}
 static void CopyTree(string source,string dest){Directory.CreateDirectory(dest);foreach(var f in Directory.GetFiles(source))File.Copy(f,Path.Combine(dest,Path.GetFileName(f)),true);foreach(var d in Directory.GetDirectories(source))CopyTree(d,Path.Combine(dest,Path.GetFileName(d)));}
 static async Task ProcessRun(string exe,string args,string cwd,Action<string,double> report,CancellationToken token){var info=new ProcessStartInfo(exe,"-I -u "+args){WorkingDirectory=cwd,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};info.EnvironmentVariables["PYTHONIOENCODING"]="utf8";info.EnvironmentVariables["PYTHONUTF8"]="1";Directory.CreateDirectory(Path.Combine(Paths.Engines,"cache/tmp"));info.EnvironmentVariables["TEMP"]=Path.Combine(Paths.Engines,"cache/tmp");info.EnvironmentVariables["TMP"]=Path.Combine(Paths.Engines,"cache/tmp");info.EnvironmentVariables["PIP_CACHE_DIR"]=Path.Combine(Paths.Engines,"DownloadCache/pip");info.EnvironmentVariables["NLTK_DATA"]=Path.Combine(Paths.Engines,"nltk-data");info.EnvironmentVariables["MPLCONFIGDIR"]=Path.Combine(Paths.Engines,"cache/matplotlib");info.EnvironmentVariables["XDG_CACHE_HOME"]=Path.Combine(Paths.Engines,"cache");info.EnvironmentVariables["HF_HOME"]=Path.Combine(Paths.Engines,"hf-cache");info.EnvironmentVariables["PATH"]=Path.GetDirectoryName(exe)+";"+Path.Combine(Path.GetDirectoryName(exe),"Scripts")+";"+Path.Combine(Paths.App,"tools")+";"+Environment.GetEnvironmentVariable("PATH");using(var p=new Process{StartInfo=info}){string activeDownload="运行依赖";p.OutputDataReceived+=(sender,e)=>{if(e.Data!=null){Paths.Log(e.Data);if(e.Data.TrimStart().StartsWith("Downloading "))activeDownload=e.Data.Trim();var m=System.Text.RegularExpressions.Regex.Match(e.Data,@"Progress\s+(\d+)\s+of\s+(\d+)");if(m.Success&&double.Parse(m.Groups[2].Value)>0)report(activeDownload+"\n"+(double.Parse(m.Groups[1].Value)/1048576).ToString("F1")+" / "+(double.Parse(m.Groups[2].Value)/1048576).ToString("F1")+" MB",100*double.Parse(m.Groups[1].Value)/double.Parse(m.Groups[2].Value));else report(e.Data,-1);}};p.ErrorDataReceived+=(s,e)=>{if(e.Data!=null){Paths.Log(e.Data);report(e.Data,-1);}};p.Start();p.StandardInput.Close();p.BeginOutputReadLine();p.BeginErrorReadLine();using(token.Register(()=>{try{Process.Start(new ProcessStartInfo("taskkill.exe","/PID "+p.Id+" /T /F"){CreateNoWindow=true,UseShellExecute=false});}catch{}})){await Task.Run(()=>p.WaitForExit());token.ThrowIfCancellationRequested();if(p.ExitCode!=0)throw new IOException("自动配置失败，错误码 "+p.ExitCode+"。详细日志：App/Config/native.log");}}}
 static string Quote(string value){return "\""+value.Replace("\"","\\\"")+"\"";}
 static async Task Nltk(string python,string cwd,Action<string,double> report,CancellationToken token){string folder=Path.Combine(Paths.Engines,"nltk-data").Replace("\\","/");await ProcessRun(python,"-c \"import nltk; [nltk.download(n, download_dir='"+folder+"') for n in ['averaged_perceptron_tagger','averaged_perceptron_tagger_eng','cmudict']]\"",cwd,report,token);}
 static async Task Torch(string folder,Action<string,double> report,CancellationToken token){string[] packages={"torch","torchaudio"};var wheels=new System.Collections.Generic.List<string>();foreach(string package in packages){string index="https://download.pytorch.org/whl/cu128/"+package+"/";string html=await Text(index,token);string pattern="href=[\"']([^\"']*"+package+"-2[.]8[.]0(?:%2B|[+])cu128-cp310-cp310-win_amd64[.]whl)#sha256=([a-f0-9]{64})";var match=System.Text.RegularExpressions.Regex.Match(html,pattern,System.Text.RegularExpressions.RegexOptions.IgnoreCase);if(!match.Success)throw new IOException("官方索引中找不到固定版本 "+package);var url=new Uri(new Uri(index),WebUtility.HtmlDecode(match.Groups[1].Value));if(url.Scheme!="https"||!url.Host.EndsWith(".pytorch.org",StringComparison.OrdinalIgnoreCase))throw new IOException("拒绝非官方 PyTorch 下载源");string name=Uri.UnescapeDataString(Path.GetFileName(url.AbsolutePath));string target=Path.Combine(Paths.Engines,"DownloadCache/wheels/"+name);await RangeDownload.Run(url.ToString(),target,0,match.Groups[2].Value.ToLowerInvariant(),report,token);wheels.Add(Quote(target));}await ProcessRun(Path.Combine(folder,"python.exe"),"-m pip install --progress-bar raw --disable-pip-version-check --no-warn-script-location "+String.Join(" ",wheels),folder,report,token);}
 static async Task Python(string folder,string version,string zipname,string requirements,Action<string,double> report,CancellationToken token){bool repair=File.Exists(Path.Combine(folder,".ready"));if(!File.Exists(Path.Combine(folder,"python.exe"))){var cache=Path.Combine(Paths.Engines,"DownloadCache");Directory.CreateDirectory(cache);string zip=Path.Combine(cache,zipname);await Download("https://www.python.org/ftp/python/"+version+"/"+zipname,zip,0,null,false,report,token);report("正在解压独立运行环境",-1);Unzip(zip,folder);string pth=Directory.GetFiles(folder,"python*._pth").First();string stdlib=Directory.GetFiles(folder,"python*.zip").Select(Path.GetFileName).First();File.WriteAllText(pth,stdlib+"\n.\nLib\\site-packages\nimport site\n",Encoding.ASCII);}
 Directory.CreateDirectory(Path.Combine(folder,"Lib/site-packages"));File.WriteAllText(Path.Combine(folder,"Lib/site-packages/sitecustomize.py"),"import os,ctypes\nif os.name=='nt':\n try:\n  _crt=ctypes.CDLL('ucrtbase.dll');_crt.setlocale.argtypes=[ctypes.c_int,ctypes.c_char_p];_crt.setlocale.restype=ctypes.c_char_p;_crt.setlocale(0,b'.UTF8')\n except Exception:pass\n",Encoding.UTF8);string pip=Path.Combine(folder,"get-pip.py");if(!File.Exists(Path.Combine(folder,"Lib/site-packages/pip/__init__.py"))){string url=version.StartsWith("3.9")?"https://bootstrap.pypa.io/pip/3.9/get-pip.py":"https://bootstrap.pypa.io/get-pip.py";await Download(url,pip,0,null,false,report,token);await ProcessRun(Path.Combine(folder,"python.exe"),Quote(pip)+" --disable-pip-version-check --no-warn-script-location",folder,report,token);}
 report("正在自动安装运行依赖；此阶段按安装器输出显示状态",-1);if(version.StartsWith("3.10"))await Torch(folder,report,token);await ProcessRun(Path.Combine(folder,"python.exe"),"-m pip install --progress-bar raw --disable-pip-version-check --no-warn-script-location --prefer-binary "+(repair?"--force-reinstall ":"")+"--find-links "+Quote(Path.Combine(Paths.Engines,"DownloadCache/wheels"))+" -r "+Quote(requirements),folder,report,token);}
 static async Task Repo(string repo,string dest,HashSet<string> include,Action<string,double> report,CancellationToken token){report("读取模型文件清单："+repo,-1);string revisionPath=repo=="IndexTeam/IndexTTS-2"?"/revision/740dcaff396282ffb241903d150ac011cd4b1ede":"";string json=await Text("https://huggingface.co/api/models/"+repo+revisionPath+"?blobs=true",token);token.ThrowIfCancellationRequested();var info=Paths.Obj(Paths.Json.DeserializeObject(json));string revision=Paths.S(info,"sha");if(String.IsNullOrEmpty(revision))throw new IOException("模型版本清单不完整");var files=Paths.Arr(info["siblings"]);int number=0;foreach(var item in files){token.ThrowIfCancellationRequested();var f=Paths.Obj(item);string name=Paths.S(f,"rfilename");if(include!=null&&!include.Contains(name))continue;if(name.EndsWith(".md")||name==".gitattributes"||!name.StartsWith(".")){number++;var lfs=Paths.Obj(f.ContainsKey("lfs")?f["lfs"]:null);string hash=Paths.S(lfs,"sha256");bool git=hash=="";if(git)hash=Paths.S(f,"blobId");long size=0;if(lfs.ContainsKey("size"))size=Convert.ToInt64(lfs["size"]);else if(f.ContainsKey("size"))size=Convert.ToInt64(f["size"]);string url="https://huggingface.co/"+repo+"/resolve/"+revision+"/"+String.Join("/",name.Split('/').Select(Uri.EscapeDataString));await Download(url,Combine(dest,name),size,hash,git,report,token);}}}
 public static async Task ColdIndexTest(){string target=Path.Combine(Paths.Engines,"downloads/model-runtime-test");Action<string,double> report=(message,value)=>Paths.Log(message);await Python(target,"3.10.11","python-3.10.11-embed-amd64.zip",Path.Combine(Paths.App,"EngineAdapter/index-requirements.txt"),report,CancellationToken.None);string nltk=Path.Combine(Paths.Engines,"nltk-data").Replace("\\","/");await ProcessRun(Path.Combine(target,"python.exe"),"-c \"import nltk; [nltk.download(n, download_dir='"+nltk+"') for n in ['averaged_perceptron_tagger','averaged_perceptron_tagger_eng','cmudict']]\"",Paths.App,report,CancellationToken.None);await ProcessRun(Path.Combine(target,"python.exe"),Quote(Path.Combine(Paths.App,"studio_emotion_stage.py"))+" "+Quote(Path.Combine(Paths.Data,"native-test-job.json")),Path.Combine(Paths.Engines,"IndexTTS2"),report,CancellationToken.None);File.WriteAllText(Path.Combine(Paths.Data,"native-cold-index-test.json"),"{\"passed\":true}");}
 public static async Task ColdRuntimeTest(){string target=Path.Combine(Paths.Engines,"downloads/runtime-test");await Python(target,"3.9.13","python-3.9.13-embed-amd64.zip",Path.Combine(Paths.App,"EngineAdapter/core-requirements.txt"),(message,value)=>Paths.Log(message),CancellationToken.None);await ProcessRun(Path.Combine(target,"python.exe"),"-c \"import numpy,scipy,sounddevice,soundfile,psutil\"",Paths.App,(message,value)=>Paths.Log(message),CancellationToken.None);File.WriteAllText(Path.Combine(Paths.Data,"native-cold-runtime-test.json"),"{\"passed\":true}");}
 public static async Task SelfTest(){var records=Paths.Arr(Paths.Json.DeserializeObject(File.ReadAllText(Path.Combine(Paths.App,"EngineAdapter/voices.json"),Encoding.UTF8)));var first=Paths.Obj(records[0]);string target=Path.Combine(Paths.Engines,"downloads/self-test/dante.wav");int notifications=0;await Download(Paths.S(first,"url"),target,0,Paths.S(first,"sha256"),false,(message,value)=>{notifications++;},CancellationToken.None);await Repo("IndexTeam/IndexTTS-2",Path.Combine(Paths.Engines,"downloads/self-test/model-manifest"),new HashSet<string>(new[]{"config.yaml"}),(message,value)=>{notifications++;},CancellationToken.None);bool rejected=false;try{Combine(Paths.Engines,"../escape");}catch(IOException){rejected=true;}if(!rejected)throw new Exception("Path traversal guard failed");File.WriteAllText(Path.Combine(Paths.Data,"native-download-test.json"),Paths.Json.Serialize(new Dictionary<string,object>{{"download",true},{"sha256",Digest(target,false)},{"progress_notifications",notifications},{"traversal_rejected",true}}));}
 public static async Task Install(Action<string,double> report,CancellationToken token){await InstallComponent(-1,report,token);}
 public static async Task InstallComponent(int component,Action<string,double> report,CancellationToken token){string core=Path.GetDirectoryName(Paths.CorePython);if((component==-1||component==0)&&!CoreReady()){await Python(core,"3.9.13","python-3.9.13-embed-amd64.zip",Path.Combine(Paths.App,"EngineAdapter/core-requirements.txt"),report,token);await ProcessRun(Paths.CorePython,"-c \"import numpy, scipy, sounddevice, soundfile, psutil\"",Paths.App,report,token);File.WriteAllText(Path.Combine(core,".ready"),"validated");}
 string index=Path.Combine(Paths.Engines,"IndexTTS2");string env=Path.Combine(index,".venv");if((component==-1||component==1)&&(!File.Exists(Path.Combine(env,".ready"))||!File.Exists(Path.Combine(env,"Lib/site-packages/torch/__init__.py")))){await Python(env,"3.10.11","python-3.10.11-embed-amd64.zip",Path.Combine(Paths.App,"EngineAdapter/index-requirements.txt"),report,token);CopyTree(Path.Combine(Paths.App,"EngineAdapter/indextts"),Path.Combine(index,"indextts"));}
 if((component==-1||component==1)&&!ModelReady()){await Repo("IndexTeam/IndexTTS-2",Path.Combine(index,"checkpoints_2"),null,report,token);string aux=Path.Combine(index,"checkpoints_2/hf_cache");await Repo("facebook/w2v-bert-2.0",Path.Combine(aux,"w2v-bert-2.0"),new HashSet<string>(new[]{"config.json","preprocessor_config.json","model.safetensors"}),report,token);await Repo("amphion/MaskGCT",aux,new HashSet<string>(new[]{"semantic_codec/model.safetensors"}),report,token);string codec=Path.Combine(aux,"semantic_codec/model.safetensors");if(File.Exists(codec))File.Copy(codec,Path.Combine(aux,"semantic_codec_model.safetensors"),true);await Repo("funasr/campplus",aux,new HashSet<string>(new[]{"campplus_cn_common.bin"}),report,token);await Repo("nvidia/bigvgan_v2_22khz_80band_256x",Path.Combine(aux,"bigvgan"),new HashSet<string>(new[]{"config.json","bigvgan_generator.pt"}),report,token);await Repo("pengzhendong/wetext",Path.Combine(Paths.Engines,"wetext-model"),null,report,token);await Nltk(Paths.ModelPython,index,report,token);await ProcessRun(Paths.ModelPython,"-c \"import sys,os; sys.path.insert(0,os.getcwd()); from indextts.infer_v2 import IndexTTS2; import torch\"",index,report,token);File.WriteAllText(Path.Combine(env,".ready"),"validated");File.WriteAllText(Path.Combine(index,".ready"),"validated");}
 string voices=Path.Combine(Paths.Engines,"voices");var records=Paths.Arr(Paths.Json.DeserializeObject(File.ReadAllText(Path.Combine(Paths.App,"EngineAdapter/voices.json"),Encoding.UTF8)));foreach(var item in records){var f=Paths.Obj(item);if(component!=-1&&Paths.S(f,"file")!=(component==2?"dante.wav":component==3?"narrator.wav":""))continue;await Download(Paths.S(f,"url"),Combine(voices,Paths.S(f,"file")),0,Paths.S(f,"sha256"),false,report,token);}report("下载与配置完成",100);}
}
